private suspend fun transactionsCommittedRecordsAreReadBoundary(
    finiteCase: LawSpecRuntime.FiniteCase
) {
    val symbols = mutableMapOf<String, Any>()
    val values = finiteCase.values(symbols)
    val t = LawSpecRuntime.convert("Text", values[0], MACHINE_BITS)
    val txid = LawSpecRuntime.convert("Text", values[1], MACHINE_BITS)
    val first =
        SCHEMA.validate(
            LawSpecSchema.Named("lawtwin.kafka.model::type::Record"),
            values[2],
            MACHINE_BITS,
            symbols,
        )
    val second =
        SCHEMA.validate(
            LawSpecSchema.Named("lawtwin.kafka.model::type::Record"),
            values[3],
            MACHINE_BITS,
            symbols,
        )
    val withCluster =
        callAdapterConnectCluster(
            symbols,
            { LawSpecRuntime.convert("Unit", LawSpecRuntime.absent("Unit"), MACHINE_BITS) },
        )
    try {
        LawSpecRuntime.installHandlers(
            symbols,
            mapOf(
                "lawtwin.kafka::ability::Transactions" to
                    Kafka.TransactionsHandler(
                        LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                            .decode(withCluster)
                    ),
                "lawtwin.kafka::ability::Broker" to
                    Kafka.BrokerHandler(
                        LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                            .decode(withCluster)
                    ),
            ),
        )
        transactionsCommittedRecordsAreReadCheck(
            "lawtwin.kafka::Transactions: |committed records are read committed together and in order| [native] boundary " +
                finiteCase.index() +
                " — ../src/contract.lawspec:1678",
            symbols,
            arrayOf<LawSpecRuntime.Value>(t, txid, first, second, withCluster),
        )
    } finally {
        callAdapterDisconnectCluster(symbols, { withCluster })
    }
}

