private suspend fun transactionsCommittedRecordsAreRead2Boundary(
    finiteCase: LawSpecRuntime.FiniteCase
) {
    val symbols = mutableMapOf<String, Any>()
    val values = finiteCase.values(symbols)
    val sharedCluster = lawspec.abilities.lawtwin.Kafka.Cluster(symbols)
    LawSpecRuntime.installHandlers(
        symbols,
        mapOf(
            "lawtwin.kafka::ability::Transactions" to
                lawspec.abilities.lawtwin.Kafka.KafkaTransactions(symbols),
            "lawtwin.kafka::ability::Broker" to sharedCluster,
            "lawtwin.kafka::ability::Partitioner" to
                lawspec.abilities.lawtwin.Kafka.MurmurPartitioner(symbols),
        ),
    )
    val t = LawSpecRuntime.convert("Text", values[0], MACHINE_BITS)
    val txid = LawSpecRuntime.convert("Text", values[1], MACHINE_BITS)
    val first =
        SCHEMA.validate(
            LawSpecSchema.Named("lawtwin.kafka.model::type::Record"),
            values[2],
            MACHINE_BITS,
            symbols,
        )
    val second =
        SCHEMA.validate(
            LawSpecSchema.Named("lawtwin.kafka.model::type::Record"),
            values[3],
            MACHINE_BITS,
            symbols,
        )
    transactionsCommittedRecordsAreRead2Check(
        "lawtwin.kafka::Transactions: |committed records are read committed together and in order| [reference] boundary " +
            finiteCase.index() +
            " — ../src/contract.lawspec:1678",
        symbols,
        arrayOf<LawSpecRuntime.Value>(t, txid, first, second),
    )
}

