private fun StringSpec.murmur2AgreesWithKafka(
    register: (String, suspend TestScope.() -> kotlin.Unit) -> kotlin.Unit
) {
    operator fun String.invoke(test: suspend TestScope.() -> kotlin.Unit) = register(this, test)
    // |murmur2 agrees with Kafka| — ../src/contract.lawspec:1118
    // References: KAFKA-murmur2
    // murmur2 (Utf8("21")) = 3321034988 and murmur2 (Utf8("foobar")) = 3504634814 and murmur2
    // (Utf8("a-little-bit-long-string")) = 3308985760 and murmur2
    // (Utf8("a-little-bit-longer-string")) = 2808662467 and murmur2
    // (Utf8("lkjh234lh9fiuh90y23oiuhsafujhadof229phr9h19h89h8")) = 4236069325 and murmur2
    // (Utf8("abc")) = 479470107
    for (finiteCase in LawSpecRuntime.finiteCases(murmur2AgreesWithKafkaCases1)) {
        ("murmur2AgreesWithKafka_boundary" + finiteCase.index()) {
            murmur2AgreesWithKafkaBoundary(finiteCase)
        }
    }
}

private fun StringSpec.brokerOffsetsInPartitionAreDenseAnd(
    register: (String, suspend TestScope.() -> kotlin.Unit) -> kotlin.Unit
) {
    operator fun String.invoke(test: suspend TestScope.() -> kotlin.Unit) = register(this, test)
    // Broker: |offsets in a partition are dense and increasing| [native] —
    // ../src/contract.lawspec:69
    // Two batches produced one after the other to one partition get offsets
    // that follow on: the second starts where the first ends.
    // for all (t :: Text) (first :: List (lawtwin.kafka.model::type::Record)) (second :: List
    // (lawtwin.kafka.model::type::Record)) => created t 1 implies let tp = let _lawspecRecordField0
    // = t in let _lawspecRecordField1 = 0 in
    // lawtwin.kafka.model::type::TopicPartition::TopicPartition(_lawspecRecordField0,
    // _lawspecRecordField1) in let a = attempt (produceRequest tp (Maybe::Absent()) first) in let b
    // = attempt (produceRequest tp (Maybe::Absent()) second) in followsBatch a first b = true end
    // for all
    for (finiteCase in LawSpecRuntime.finiteCases(brokerOffsetsInPartitionAreDenseAndCases10)) {
        ("brokerOffsetsInPartitionAreDenseAnd_boundary" + finiteCase.index()) {
            brokerOffsetsInPartitionAreDenseAndBoundary(finiteCase)
        }
    }

    "brokerOffsetsInPartitionAreDenseAnd_property: lawtwin.kafka::Broker: |offsets in a partition are dense and increasing| [native]" {
        checkAll(
            LawSpecTesting.config(100),
            LawSpecTesting.filter(
                LawSpecTesting.inputs(
                    lawspecChoice(
                        Arb.element(
                            run {
                                val symbols = mutableMapOf<String, Any>()
                                listOf(
                                    LawSpecRuntime.text("Text", "-"),
                                    LawSpecRuntime.text("Text", "o"),
                                    LawSpecRuntime.text("Text", "t"),
                                    LawSpecRuntime.text("Text", "7oIEcKM"),
