private fun StringSpec.brokerTheCoordinatorAssignsEveryPartition(
    register: (String, suspend TestScope.() -> kotlin.Unit) -> kotlin.Unit
) {
    operator fun String.invoke(test: suspend TestScope.() -> kotlin.Unit) = register(this, test)
    // Broker: |the coordinator assigns every partition exactly once| [native] —
    // ../src/contract.lawspec:212
    // After members join, the partitions of the topic they subscribe to are
    // shared out so that each partition has exactly one owner in the
    // generation.
    // References: KIP-848
    // for all (t :: Text) (n :: Int32) (g :: Text) (ids :: List (Text)) => created t n implies
    // (joinAll g (memberIds ids) (List::Cons(t, List::Nil())) And coversOnce t n
    // (describeGroupRequest g)) = true end for all
    val searchInputs = listOf("(text)", "(int Int32 1 16)", "(text)", "(list (text))")

    val searchCase: suspend (List<LawSpecRuntime.Value>) -> Double? = searchCase@{ values ->
        val symbols = mutableMapOf<String, Any>()
        val t = LawSpecRuntime.convert("Text", values[0], MACHINE_BITS)
        val n = LawSpecRuntime.convert("Int32", values[1], MACHINE_BITS)
        val g = LawSpecRuntime.convert("Text", values[2], MACHINE_BITS)
        val ids =
            SCHEMA.validate(
                LawSpecSchema.Named("List", LawSpecSchema.Named("Text")),
                values[3],
                MACHINE_BITS,
                symbols,
            )
        if (
            !(LawSpecRuntime.truth(
                lawspec.runtime.LawSpecDefinitionBodies.lawtwinKafkaModelValidTopicName(symbols, t)
            ) &&
                LawSpecRuntime.truth(
                    LawSpecRuntime.bool(
                        LawSpecRuntime.truth(
                            LawSpecRuntime.binary(">=", n, LawSpecRuntime.integer("Integer", "1"))
                        ) &&
                            LawSpecRuntime.truth(
                                LawSpecRuntime.binary(
                                    "<=",
                                    n,
                                    LawSpecRuntime.integer("Integer", "16"),
                                )
                            )
                    )
                ) &&
                LawSpecRuntime.truth(
                    LawSpecRuntime.binary("!=", g, LawSpecRuntime.text("Text", ""))
                ) &&
                LawSpecRuntime.truth(
                    LawSpecRuntime.bool(
                        !LawSpecRuntime.truth(
                            LawSpecKotlinCodecs.match(
                                SCHEMA,
                                LawSpecSchema.Named("List", LawSpecSchema.Named("Text")),
                                lawspec.runtime.LawSpecDefinitionBodies.memberIds(symbols, ids),
                                MACHINE_BITS,
                                symbols,
                            ) { tag, fields ->
                                when (tag) {
                                    "List::Nil" -> {
                                        LawSpecRuntime.bool(true)
                                    }
                                    "List::Cons" -> {
                                        val head = fields[0]
                                        val tail = fields[1]
                                        LawSpecRuntime.bool(false)
                                    }
                                    else -> {
                                        throw IllegalArgumentException(
                                            "invalid checked match constructor"
                                        )
                                    }
                                }
                            }
                        )
                    )
                ))
        ) {
            return@searchCase null
        }
        val withCluster =
            callAdapterConnectCluster(
                symbols,
                { LawSpecRuntime.convert("Unit", LawSpecRuntime.absent("Unit"), MACHINE_BITS) },
            )
        try {
            LawSpecRuntime.installHandlers(
                symbols,
                mapOf(
                    "lawtwin.kafka::ability::Broker" to
                        Kafka.BrokerHandler(
                            LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                                .decode(withCluster)
                        )
                ),
            )
            brokerTheCoordinatorAssignsEveryPartitionCheck(
                "lawtwin.kafka::Broker: |the coordinator assigns every partition exactly once| [native] search — ../src/contract.lawspec:212",
                symbols,
                arrayOf<LawSpecRuntime.Value>(t, n, g, ids, withCluster),
            )
        } finally {
            callAdapterDisconnectCluster(symbols, { withCluster })
        }
        0.0
    }

    "brokerTheCoordinatorAssignsEveryPartition_replay" {
        LawSpecRuntime.searchReplay(
            "lawtwin.kafka::Broker: |the coordinator assigns every partition exactly once| [native]",
            searchInputs,
            LawSpecRuntime.SearchCase { values ->
                kotlinx.coroutines.runBlocking { searchCase(values) }
            },
        )
    }

    for (finiteCase in
        LawSpecRuntime.finiteCases(brokerTheCoordinatorAssignsEveryPartitionCases1)) {
        ("brokerTheCoordinatorAssignsEveryPartition_boundary" + finiteCase.index()) {
            brokerTheCoordinatorAssignsEveryPartitionBoundary(finiteCase)
        }
    }

    "brokerTheCoordinatorAssignsEveryPartition_property: lawtwin.kafka::Broker: |the coordinator assigns every partition exactly once| [native]" {
        checkAll(
            LawSpecTesting.config(100),
            LawSpecTesting.filter(
                LawSpecTesting.inputs(
