private fun StringSpec.transactionsTransactionMustBeginBeforeIt(
    register: (String, suspend TestScope.() -> kotlin.Unit) -> kotlin.Unit
) {
    operator fun String.invoke(test: suspend TestScope.() -> kotlin.Unit) = register(this, test)
    // Transactions: |a transaction must begin before it ends| [native] —
    // ../src/contract.lawspec:1720
    // for all (txid :: Text) => let id = initTransactions txid in commitTransaction =
    // Either::Left(lawtwin.kafka.model::type::KafkaError::IllegalState()) end for all
    val searchInputs = listOf("(text)")

    val searchCase: suspend (List<LawSpecRuntime.Value>) -> Double? = searchCase@{ values ->
        val symbols = mutableMapOf<String, Any>()
        val txid = LawSpecRuntime.convert("Text", values[0], MACHINE_BITS)
        if (
            !(LawSpecRuntime.truth(
                LawSpecRuntime.binary("!=", txid, LawSpecRuntime.text("Text", ""))
            ))
        ) {
            return@searchCase null
        }
        val withCluster =
            callAdapterConnectCluster(
                symbols,
                { LawSpecRuntime.convert("Unit", LawSpecRuntime.absent("Unit"), MACHINE_BITS) },
            )
        try {
            LawSpecRuntime.installHandlers(
                symbols,
                mapOf(
                    "lawtwin.kafka::ability::Transactions" to
                        Kafka.TransactionsHandler(
                            LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                                .decode(withCluster)
                        )
                ),
            )
            transactionsTransactionMustBeginBeforeItCheck(
                "lawtwin.kafka::Transactions: |a transaction must begin before it ends| [native] search — ../src/contract.lawspec:1720",
                symbols,
                arrayOf<LawSpecRuntime.Value>(txid, withCluster),
            )
        } finally {
            callAdapterDisconnectCluster(symbols, { withCluster })
        }
        0.0
    }

    "transactionsTransactionMustBeginBeforeIt_replay" {
        LawSpecRuntime.searchReplay(
            "lawtwin.kafka::Transactions: |a transaction must begin before it ends| [native]",
            searchInputs,
            LawSpecRuntime.SearchCase { values ->
                kotlinx.coroutines.runBlocking { searchCase(values) }
