        )
    }

    for (finiteCase in LawSpecRuntime.finiteCases(transactionsTransactionMustBeginBeforeItCases2)) {
        ("transactionsTransactionMustBeginBeforeIt_boundary" + finiteCase.index()) {
            transactionsTransactionMustBeginBeforeItBoundary(finiteCase)
        }
    }

    "transactionsTransactionMustBeginBeforeIt_property: lawtwin.kafka::Transactions: |a transaction must begin before it ends| [native]" {
        checkAll(LawSpecTesting.config(100), Arb.int()) { seed ->
            val symbols = mutableMapOf<String, Any>()
