                                )
                            },
                        )
                    try {
                        LawSpecRuntime.installHandlers(
                            symbols,
                            mapOf(
                                "lawtwin.kafka::ability::Transactions" to
                                    Kafka.TransactionsHandler(
                                        LawSpecDataCodecs.clusterCodec(
                                                SCHEMA,
                                                MACHINE_BITS,
                                                symbols,
                                            )
                                            .decode(withCluster)
                                    )
                            ),
                        )
                        try {
                            transactionsTransactionMustBeginBeforeItCheck(
                                "lawtwin.kafka::Transactions: |a transaction must begin before it ends| [native] property — ../src/contract.lawspec:1720",
                                symbols,
                                arrayOf<LawSpecRuntime.Value>(txid, withCluster),
